from IPython.display import Image, display as ipy_display
from pathlib import Path

def show(path: str, caption: str = '') -&gt; None:
    p = Path(f'../data/{path}')
    if p.exists():
        ipy_display(Image(str(p), width=900))
    if caption:
        print(f'↑ {caption}\n')
